function cloneMaterial(mat){if(!mat)return new THREE.MeshStandardMaterial({color:0x8b6540,roughness:.9,metalness:.02,side:THREE.FrontSide});const clone=mat.clone();if('side'in clone)clone.side=THREE.FrontSide;return clone;}
function disposeObject(root){root?.traverse?.(object=>{object.geometry?.dispose?.();const materials=Array.isArray(object.material)?object.material:object.material?[object.material]:[];for(const material of materials)material?.dispose?.();});}
function clearGroup(group){if(!group)return;while(group.children.length){const child=group.children[group.children.length-1];group.remove(child);disposeObject(child);}}
function basename(name){return String(name||'ruin').replace(/\.[^.]+$/,'').replace(/[^a-z0-9_-]+/gi,'_').replace(/^_+|_+$/g,'')||'ruin';}
function download(name,blob){const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function rawTextureUrl(path){return REPO_RAW_ROOT+String(path||'').replace(/^\/+/, '');}
function hexToNum(value){const s=String(value||'#000000').replace('#','');return parseInt(s.length===3?s.split('').map(ch=>ch+ch).join(''):s,16)||0;}
function hexToRgb(value){const n=hexToNum(value);return[(n>>16)&255,(n>>8)&255,n&255];}
function relativeLuminance(r,g,b){return(.2126*r+.7152*g+.0722*b)/255;}
function shadeFillConfig(){return{shadowFloor:.18,highlightBoost:1.18,neutralLuminance:.55,gamma:1,preserveNearBlackOutlines:true,outlineThreshold:.08};}
function adaptiveShadeNeutral(pixels,cfg){const luminances=[],pixelCount=pixels.length/4,step=Math.max(1,Math.floor(pixelCount/60000));for(let pixel=0;pixel<pixelCount;pixel+=step){const i=pixel*4;if(pixels[i+3]<16)continue;const lum=relativeLuminance(pixels[i],pixels[i+1],pixels[i+2]);if(cfg.preserveNearBlackOutlines&&lum<=cfg.outlineThreshold)continue;luminances.push(lum);}if(!luminances.length)return Math.max(.0001,cfg.neutralLuminance);luminances.sort((a,b)=>a-b);const middle=Math.floor(luminances.length/2),median=luminances.length%2?luminances[middle]:(luminances[middle-1]+luminances[middle])*.5;return clamp(median,.04,.98);}
function shadeFillPixels(pixels,targetRgb){const cfg=shadeFillConfig(),neutral=adaptiveShadeNeutral(pixels,cfg),[tr,tg,tb]=targetRgb;for(let i=0;i<pixels.length;i+=4){if(!pixels[i+3])continue;const lum=relativeLuminance(pixels[i],pixels[i+1],pixels[i+2]);if(cfg.preserveNearBlackOutlines&&lum<=cfg.outlineThreshold)continue;const normalized=Math.pow(Math.max(0,lum)/neutral,cfg.gamma),shade=clamp(normalized,cfg.shadowFloor,cfg.highlightBoost);pixels[i]=clamp(Math.round(tr*shade),0,255);pixels[i+1]=clamp(Math.round(tg*shade),0,255);pixels[i+2]=clamp(Math.round(tb*shade),0,255);}}
function loadRepoImage(path){const key=String(path||'');if(sourceImageCache.has(key))return sourceImageCache.get(key);const promise=new Promise((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.onload=()=>resolve(image);image.onerror=()=>reject(new Error(`Failed to load repository PNG: ${key}`));image.src=rawTextureUrl(key);}).catch(error=>{sourceImageCache.delete(key);throw error;});sourceImageCache.set(key,promise);return promise;}
function processedRepoTexture(path,fillEnabled=false,fillColor='#ffffff'){const key=JSON.stringify([path,!!fillEnabled,String(fillColor||'#ffffff').toLowerCase()]);if(processedTextureCache.has(key))return processedTextureCache.get(key);const promise=loadRepoImage(path).then(image=>{const w=Math.max(1,image.naturalWidth||image.width||1),h=Math.max(1,image.naturalHeight||image.height||1),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,w,h);if(fillEnabled){const data=context.getImageData(0,0,w,h);shadeFillPixels(data.data,hexToRgb(fillColor));context.putImageData(data,0,0);}const texture=new THREE.CanvasTexture(canvas);texture.encoding=THREE.sRGBEncoding;texture.wrapS=texture.wrapT=THREE.ClampToEdgeWrapping;texture.needsUpdate=true;texture.name=(path.split('/').pop()||'repo_png')+(fillEnabled?`_fill_${String(fillColor).replace('#','')}`:'');return texture;}).catch(error=>{processedTextureCache.delete(key);throw error;});processedTextureCache.set(key,promise);return promise;}
function applyRepoTextureAsync(material,assignment){if(!assignment?.enabled||!assignment.path)return material;processedRepoTexture(assignment.path,assignment.fillEnabled,assignment.fillColor).then(texture=>{material.map=texture;if(material.color)material.color.setHex(0xffffff);material.needsUpdate=true;}).catch(error=>log(`Texture replacement failed (${assignment.path}): ${error.message}`,'error'));return material;}
function assignmentMaterial(baseMaterial,assignment){const material=cloneMaterial(baseMaterial);return applyRepoTextureAsync(material,assignment);}
function interiorMaterial(cfg,side=THREE.FrontSide){const spec=cfg.interiorMaterial||{},fallbackColor=spec.fillColor||cfg.interiorColor||'#4d4d4d',material=new THREE.MeshStandardMaterial({color:new THREE.Color(fallbackColor),roughness:clamp((spec.roughness??cfg.interiorRough??95)/100,.02,1),metalness:0,side});if(spec.enabled&&spec.path)applyRepoTextureAsync(material,{enabled:true,path:spec.path,fillEnabled:!!spec.fillEnabled,fillColor:fallbackColor});return material;}
async function getRepoTree(){if(repoTreePromise)return repoTreePromise;repoTreePromise=fetch(REPO_TREE_URL,{headers:{Accept:'application/vnd.github+json'}}).then(response=>{if(!response.ok)throw new Error(`GitHub tree HTTP ${response.status}`);return response.json();}).catch(error=>{repoTreePromise=null;throw error;});return repoTreePromise;}
