function renderTextureLibrary(){const query=$('textureSearch').value.trim().toLowerCase(),filtered=repoPngPaths.filter(path=>!query||path.toLowerCase().includes(query)),pageSize=48,pageCount=Math.max(1,Math.ceil(filtered.length/pageSize));texturePage=clamp(texturePage,0,pageCount-1);const start=texturePage*pageSize,shown=filtered.slice(start,start+pageSize);$('texturePageStatus').textContent=filtered.length?`${start+1}–${start+shown.length} of ${filtered.length} matching PNGs · ${repoPngPaths.length} total indexed`:`0 matches · ${repoPngPaths.length} total indexed`;$('texturePrevBtn').disabled=texturePage<=0;$('textureNextBtn').disabled=texturePage>=pageCount-1;$('textureGrid').innerHTML=shown.map(path=>`<div class="textureItem ${path===selectedRepoTexturePath?'sel':''}" data-texture-path="${escapeHtml(path)}"><img loading="lazy" src="${escapeHtml(rawTextureUrl(path))}" alt=""><div class="textureName" title="${escapeHtml(path)}">${escapeHtml(path)}</div></div>`).join('')||'<div class="muted">No PNG paths match this search.</div>';document.querySelectorAll('[data-texture-path]').forEach(element=>element.onclick=()=>{selectedRepoTexturePath=element.dataset.texturePath;updateSelectedTextureUI();renderTextureLibrary();});}
async function loadRepoTextureLibrary(){const status=$('textureRepoStatus');status.textContent='Repository PNG library: loading GitHub tree…';try{const data=await getRepoTree(),paths=(Array.isArray(data.tree)?data.tree:[]).filter(entry=>entry.type==='blob'&&/\.png$/i.test(entry.path)).map(entry=>entry.path).sort((a,b)=>a.localeCompare(b));repoPngPaths=[...new Set(paths.length?paths:[DEFAULT_TEXTURE_PATH])];if(!repoPngPaths.includes(DEFAULT_TEXTURE_PATH))repoPngPaths.unshift(DEFAULT_TEXTURE_PATH);status.textContent=`Repository PNG library: ${repoPngPaths.length} PNGs indexed${data.truncated?' · GitHub reports tree truncation':''}`;status.className=data.truncated?'muted statusBad':'muted statusOk';log(`Indexed ${repoPngPaths.length} PNG files from the live HobunjiHollowUnity tree.${data.truncated?' GitHub marked the recursive tree truncated.':''}`,data.truncated?'warn':'ok');renderTextureLibrary();}catch(error){repoPngPaths=[DEFAULT_TEXTURE_PATH];status.textContent='Repository PNG library failed · carved_smooth fallback remains available';status.className='muted statusBad';renderTextureLibrary();log(`Repository PNG discovery failed: ${error.message}`,'error');}}
function furnitureLabelFromPath(path){const file=String(path||'').split('/').pop()||'';return file.replace(/\.json$/i,'').replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/[_-]+/g,' ').replace(/\b\w/g,ch=>ch.toUpperCase());}
