function renderFurnitureLibrary(){const query=$('furnitureSearch').value.trim().toLowerCase(),select=$('furnitureSelect'),current=select.value;const filtered=repoFurniturePaths.filter(path=>!query||path.toLowerCase().includes(query)||furnitureLabelFromPath(path).toLowerCase().includes(query));const groups=REPO_FURNITURE_SOURCES.map(source=>({source,paths:filtered.filter(path=>path.startsWith(source.dir))})).filter(group=>group.paths.length);select.innerHTML=groups.map(group=>`<optgroup label="${escapeHtml(group.source.label)}">${group.paths.map(path=>`<option value="${escapeHtml(path)}">${escapeHtml(furnitureLabelFromPath(path))}</option>`).join('')}</optgroup>`).join('')||'<option value="">No matching furniture</option>';if(filtered.includes(current))select.value=current;else if(filtered.length)select.value=filtered[0];$('loadRepoFurnitureBtn').disabled=!select.value;const selected=select.value,source=furnitureSourceForPath(selected);$('furnitureSelectionPath').textContent=selected?`${source?.label||'Repo'} · ${selected}`:'Repository furniture index';}
async function fetchFurnitureDirectory(dir){const url=`https://api.github.com/repos/Oolnokk/HobunjiHollowUnity/contents/${dir.replace(/\/$/,'')}?ref=main`,response=await fetch(url,{headers:{Accept:'application/vnd.github+json'}});if(!response.ok)throw new Error(`GitHub furniture directory HTTP ${response.status} (${dir})`);const entries=await response.json();return(Array.isArray(entries)?entries:[]).filter(entry=>entry.type==='file'&&/\.json$/i.test(entry.name||'')&&String(entry.path||'').startsWith(dir));}
async function loadRepoFurnitureLibrary(){const status=$('furnitureRepoStatus');status.textContent='Repository furniture library: loading GitHub tree…';try{if(!repoFurniturePromise)repoFurniturePromise=getRepoTree().then(async data=>{const tree=Array.isArray(data.tree)?data.tree:[],entries=tree.filter(entry=>entry.type==='blob'&&/\.json$/i.test(entry.path||'')&&REPO_FURNITURE_DIRS.some(dir=>String(entry.path||'').startsWith(dir)));const represented=new Set(entries.map(entry=>REPO_FURNITURE_DIRS.find(dir=>String(entry.path||'').startsWith(dir))).filter(Boolean));if(!data.truncated&&REPO_FURNITURE_DIRS.every(dir=>represented.has(dir)))return entries;const fallbacks=await Promise.all(REPO_FURNITURE_DIRS.map(fetchFurnitureDirectory));return entries.concat(...fallbacks);}).catch(error=>{repoFurniturePromise=null;throw error;});const entries=await repoFurniturePromise;repoFurniturePaths=[...new Set(entries.map(entry=>entry.path).filter(Boolean))].sort((a,b)=>{const sa=REPO_FURNITURE_DIRS.findIndex(dir=>a.startsWith(dir)),sb=REPO_FURNITURE_DIRS.findIndex(dir=>b.startsWith(dir));return sa-sb||furnitureLabelFromPath(a).localeCompare(furnitureLabelFromPath(b));});const sourceCounts=REPO_FURNITURE_SOURCES.map(source=>`${repoFurniturePaths.filter(path=>path.startsWith(source.dir)).length} ${source.label}`).join(' + ');status.textContent=`Repository furniture library: ${repoFurniturePaths.length} JSONs · ${sourceCounts}`;status.className='muted statusOk';renderFurnitureLibrary();log(`Indexed ${repoFurniturePaths.length} repository furniture JSON files across ${REPO_FURNITURE_DIRS.join(' and ')}.`,'ok');}catch(error){repoFurniturePaths=[];status.textContent='Repository furniture library failed · local JSON loading still works';status.className='muted statusBad';renderFurnitureLibrary();log(`Repository furniture discovery failed: ${error.message}`,'error');}}
