const RUIN_FURNITURE_RE=/(pillar|stone|obelisk|ruin|statue|buttress|arch|pedestal|support)/i; // Used to limit random locale selection to architectural/ruin-friendly repository furniture.
function ruinFurnitureCandidates(){const candidates=repoFurniturePaths.filter(path=>RUIN_FURNITURE_RE.test(path.split('/').pop()||''));return candidates.length?candidates:repoFurniturePaths.filter(path=>path.startsWith('docs/assets/models/furniture/data/'));}
